[Form]
public class NDXCSDCopyDialog extends FormRun
{
    boolean closedOK;
    NDXCSD lNDX_CSD;

}

public boolean closedCancel()
{
    boolean ret;

    closedOK = false;

    ret = super();

    return ret;
}

public void closeOk()
{
    closedOK = true;

    super();

    if(lNDX_CSD)
    {
        lNDX_CSD.targetCentralStoreId = CentralStoreTo.text();
    }
}

public boolean canClose()
{
    NDX_CentralStore NDX_CentralStoreTo;
    NDXTmpVerband NDX_TmpVerbandTo;
    QueryRun qr;
    boolean ret;

    ret = super();

    if(closedOK && CentralStoreFrom.valueStr() != '' && CentralStoreTo.valueStr() != '')
    {
        qr = new QueryRun(this.StoreLookup(CentralStoreTo));

        while(qr.next())
        {
            if(CentralStoreFrom.valueStr() != '')
            {
                NDX_TmpVerbandTo = qr.get(tablenum(NDXTmpVerband));
                NDX_CentralStoreTo = NDX_CentralStore::find(NDX_TmpVerbandTo.CentralStoreId);
            }
            else
            {
                NDX_CentralStoreTo = qr.get(tablenum(NDX_CentralStore));
            }

            if(NDX_CentralStoreTo.CentralStoreId == CentralStoreTo.valueStr())
            {
                break;
            }
            else
            {
                NDX_CentralStoreTo.clear();
            }
        }
    }

    if(closedOK && !NDX_CentralStoreTo)
    {
        Box::info("@NDX:NDXCentralStoreInfo12");
        ret = false;
    }

    return ret;
}

Query StoreLookup(FormControl  _ctrl)
{

    SysTableLookup          sysTableLookup;
    Query                   query = new Query();
    QueryBuildDataSource    queryBuildDataSource;
    NDX_CentralStore        lNDX_CentralStore;

    NDXVerband              lVerband;

    if(CentralStoreFrom.text() != '')
    {
        sysTableLookup = SysTableLookup::newParameters(tablenum(NDXTmpVerband), _ctrl);
        sysTableLookup.addLookupfield(fieldnum(NDXTmpVerband, CentralStoreId), true);
        sysTableLookup.addLookupMethod(tableMethodStr(NDXTmpVerband, dispCustName));
        queryBuildDataSource = query.addDataSource(tableNum(NDXTmpVerband));
    }
    else
    {
        sysTableLookup = SysTableLookup::newParameters(tablenum(NDX_CentralStore), _ctrl);
        sysTableLookup.addLookupfield(fieldnum(NDX_CentralStore, CentralStoreId), true);
        sysTableLookup.addLookupMethod(tableMethodStr(NDX_CentralStore, dispCustName));
        queryBuildDataSource = query.addDataSource(tableNum(NDX_CentralStore));
    }

    if(CentralStoreFrom.text() != '' && _ctrl.name() == 'CentralStoreTo')
    {
        lNDX_CentralStore = NDX_CentralStore::find(CentralStoreFrom.text());
        lVerband = NDXVerband::constructor();

        lVerband.getMaster(lNDX_CentralStore.CentralStoreId);

        lVerband.copyChildrenSetToList(lVerband.getDebitorsFromMaster(lVerband.masterAlliance));
        lVerband.getCSFromMaster([NDXHelperCommon::CompanyId2NDXCompany(curext(), false)], null, CentralStoreFrom.text());

        queryBuildDataSource.addRange(fieldnum(NDXTmpVerband, UmsSignature)).value(curuserid());
        queryBuildDataSource.addRange(fieldnum(NDXTmpVerband, Company)).value(curext());

    }

    sysTableLookup.parmQuery(query);

    if(CentralStoreFrom.text() != '' && _ctrl.name() == 'CentralStoreTo')
    {
        sysTableLookup.parmTmpBuffer(lVerband.parmNDXTmpVerband());
    }            
    sysTableLookup.performFormLookup();

    return query;
}

public void init()
{
    NDX_CentralStoreDistributionTable lNDX_CentralStoreDistributionTable;

    super();

    if (!element.args() ||
    !element.args().record() || element.args().dataset() != tablenum(NDX_CentralStoreDistributionTable))
    {
        throw error("@SYS22539");
    }
    else
    {
        lNDX_CSD = element.args().caller();
        lNDX_CentralStoreDistributionTable = element.args().record();
        CentralStoreFrom.text(lNDX_CentralStoreDistributionTable.CentralStoreId);
        CentralStoreFrom.allowEdit(false);
        super();
    }

    this.activateOKButton();
}

public boolean modified()
{
    boolean ret;

    ret = super();
    element.activateOKButton();
    return ret;
}
